package dev.arcane.client.gui;

import dev.arcane.api.spell.Spell;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.renderer.RenderPipelines;

/**
 * Draws a spell's icon: the 16×16 GUI sprite named by {@link Spell#icon()}. The built-in ones are in
 * {@code textures/gui/sprites/spell/}, generated by {@code tools/generate_assets.py}.
 */
public final class SpellIcons {
    private SpellIcons() {
    }

    /** Draws the spell's icon with its top-left corner at x, y. */
    public static void draw(GuiGraphics graphics, Spell spell, int x, int y) {
        graphics.blitSprite(RenderPipelines.GUI_TEXTURED, spell.icon(), x, y, 16, 16);
    }
}
